import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"63、【既济】 离下坎上","description":"周易阐真 - 63、【既济】 离下坎上","frontmatter":{"title":"63、【既济】 离下坎上","description":"周易阐真 - 63、【既济】 离下坎上"},"headers":[],"relativePath":"zh/classics/chanzhen/064.md","filePath":"zh/classics/chanzhen/064.md"}'),s={name:"zh/classics/chanzhen/064.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：既济亨，小者亨也。利贞。刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。</p></blockquote><h1 id="_63、【既济】-离下坎上" tabindex="-1">63、【既济】 离下坎上 <a class="header-anchor" href="#_63、【既济】-离下坎上" aria-label="Permalink to “63、【既济】 离下坎上”">​</a></h1><p>初九：曳其轮，濡其尾，无咎。</p><p>六二：妇丧其茀，勿逐，七日得。</p><p>九三：高宗伐鬼方，三年克之。小人勿用。</p><p>六四：需副本 有衣袽，终日戒。</p><p>九五：东邻杀牛，不如西邻之禴祭，实受其福。</p><p>上六：濡其首，厉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：水在火上，既济。君子以思患而豫防之。</p><p>既济者，事已济也。上坎水，下离火，是水在火上也。水本寒，火本燥。以火煎水，寒气化；以水制火，燥气息。水火一处，既济之象也。</p><p>君子有见于此，知修道者，颠倒阴阳，取坎填离，阴精化而真精生，识神灭而元神存，以精养神，以神摄精，精神相恋，凝结不散，还元返本，不济者既济矣。然还元返本，只完的前段工夫。若不用天然真火煅炼成真，既济极而又不济，前功俱废。以是思患而豫防之也。患者，即阴阳不济之患。当正济之时，真阴真阳合一，外来客气不得而伤。然虽不为客气所伤，而一身后天之气犹未退去，若不知沐浴温养，早为防闲，客气乘间而发，后患必有。思有患而预防之，用加减抽添之功，拔尽历劫以来根尘，阴尽阳纯，成金刚不坏之物，直至打破虚空，方为了当。若未到打破虚空地位，犹有患在。故修道者必以打破虚空，脱出真身，方为大休大歇之地也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>济者，阴阳相济之义；既济者，阴阳相济之极也。卦德上坎陷，下离明，借险以养明，以明而御险，明由险生，险因明通，明险相济，故谓既济。此防危虑险，固济丹元之卦，承上中孚而来。中孚者，悦而巽行，深造自得，阴阳不济者，终必能济矣。但不济须求济，既济须保济。保济者，固济丹元之功。固济丹元，在乎以明御险，防险养明耳。养明者，藏明于内，有智不用，有才不使，明其明德，止于至善也。防险者，谨慎于外，非礼不履，非义不行，素位而行，不愿乎外也。内既能养明，外又能防险，明有养而明不伤，险遇明而险即消。</p><p>明为离德，位于南，为火，即神也；险为坎德，位于北，为水，即精也。神好动而火上炎，以精养神，火得水而燥气悉化；精易泄而水下流，以神摄精，水得火而欲念自消。燥气化而神安，则心虚；欲念消而精一，则腹实。心虚则人心无而真阴现，腹实则道心发而真阳生。以真阴顺真阳，以真阳统真阴，真阴真阳，两而相合，恍惚有象，杳冥有精，结成一粒黍米宝珠，吞而服之，延寿无穷，是既济固有亨道也。</p><p>但阴阳既济则明盛。明盛，易于恃明自用，若不谨慎，少有疏失，明极反暗，道心又昧，人心又起，济中即有不济，是既济之亨又小也。</p><p>盖以事在未济，人多戒惧修省，用明以防险；事在既济，人每晏在自殆，昧明而招险。亨小不大，得而复失，皆在于此。是以既济亨道，惟利于守正耳。以正养明，以正防险，自然明不伤而险不生。但以明防险，尤利于既济之初。初则吉，而终则乱也。</p><p>初吉者，养明于早，有险无险；终乱者，用明太过，无险招险。总此一明，总此一险，能养其明则无险，过用其明则有险。修道者，可不于既济之初，早防其险乎?</p><p>初九，在既济之初，刚而守正，如车曳其轮而不前，人濡其尾而退后，能敬谨于始，自无咎于终。此方济，即防其不济也。</p><p>六二，柔而无刚，阴阳不济，大道难修，如妇丧其茀而有险矣。然柔而中正，炼己待时，虚室生白，神明自来，是以勿逐七日得也。七日者，火之数，炼己而火返真，以明破险，借险生明，取坎中之阳，填离中之阴，水火相济，不待勉强，自然而然。此以阴而求阳相济也。</p><p>九三，居明之极，有近于险，如有鬼方也。不能戒备于早，既济将不济，虽刚而得正者，若欲不为险伤，亦必尽其力而方保济，如高宗伐鬼方，三年克之。刚而得正者且如此，而况不正之刚乎?故曰“小人勿用”。此既济而不能豫防不济也。</p><p>六四，当既济之时，黜聪毁智，防危虑险，如舟有濡，先备衣袽，终日戒之。此既济而能时防不济也。</p><p>九五，当既济之时，满盈自居，腹实而不知虚心，既济中即藏不济，如东邻杀牛，不如西邻之禴祭，实受其福也。盖未济之时，方致济，以虚求实而能济；既济之时，济已极，实而不虚，仍不济。虚能实，满招愆，理所必然。此既济而又招不济也。</p><p>上六，火候不明，持盈未已，不能防险于既济之始，自然致险于既济之终，如濡及于首，全身失陷，阴阳散涣，前功俱废，危厉所不能免。此既济而终归不济也。</p><p>修道者，至于取坎填离，水火相济，不知费过多少苦功。幸而得之，及早封藏，防危虑险，以成有为事业。否则晏安自息，休歇罢功，火候有差，既济又不济，成而复败，可不惜乎?故有为无为之道，随时而用，必以有无一致，虚实兼该，了性了命为极功也。</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
